import{_ as o,o as a,c as t,a0 as i}from"./chunks/framework.B7o6dWmz.js";const b=JSON.parse('{"title":"MiLink 图标替换","description":"","frontmatter":{},"headers":[],"relativePath":"milink-icon-replacer/README.md","filePath":"milink-icon-replacer/README.md"}'),r={name:"milink-icon-replacer/README.md"};function d(n,e,l,s,c,h){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="milink-图标替换" tabindex="-1">MiLink 图标替换 <a class="header-anchor" href="#milink-图标替换" aria-label="Permalink to &quot;MiLink 图标替换&quot;">​</a></h1><p>一个 LSPosed 模块，用于替换小米「融合设备中心」里各类设备卡片的图标。 可以替换<strong>控制中心下拉里的融合设备卡片</strong>，以及<strong>融合设备中心（CirculateWorldActivity）里的设备列表图标</strong>。</p><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>包名</td><td><code>com.milink.iconreplacer</code></td></tr><tr><td>版本</td><td><strong>2.8.8</strong>（versionCode <strong>29</strong>）</td></tr><tr><td>适用</td><td>HyperOS4</td></tr><tr><td>模块作用域</td><td><code>com.android.systemui</code>、<code>com.milink.service</code></td></tr><tr><td>项目地址</td><td><a href="https://github.com/Yimo-Ye/milink-icon-replacer" target="_blank" rel="noreferrer">https://github.com/Yimo-Ye/milink-icon-replacer</a></td></tr></tbody></table><hr><h2 id="一、安装与启用" tabindex="-1">一、安装与启用 <a class="header-anchor" href="#一、安装与启用" aria-label="Permalink to &quot;一、安装与启用&quot;">​</a></h2><ol><li><p>安装 <code>MiLinkIconReplacer_v2.8.8-ui6.apk</code>。</p></li><li><p>打开 <strong>LSPosed</strong> → 模块 → 找到「MiLink 图标替换器」→ 启用。</p></li><li><p><strong>重要</strong>：点进模块的「作用域」，确认 <strong>两个</strong> 都被勾选：</p><ul><li>✅ <code>com.android.systemui</code>（系统界面，控制中心卡片）</li><li>✅ <code>com.milink.service</code>（融合设备中心服务）</li></ul><p>只勾选后者时，控制中心下拉里的卡片<strong>不会被替换</strong>。</p></li><li><p>保存作用域后，<strong>重启 SystemUI</strong>（或直接软重启手机），让新的作用域生效。</p></li></ol><blockquote><p>如果替换无效，<strong>第一排查点永远是：作用域是否两个都勾了、重启过没有</strong>。</p></blockquote><p>升级安装需使用同一签名（SHA-1 <code>bf88ae36d1d449055976830a2d4f3c29d87d066c</code>），否则 <code>pm install -r</code> 会失败。</p><hr><h2 id="二、模块页面" tabindex="-1">二、模块页面 <a class="header-anchor" href="#二、模块页面" aria-label="Permalink to &quot;二、模块页面&quot;">​</a></h2><p>模块自带一个设置页（打开模块图标即进入），提供：</p><ul><li><strong>总开关</strong>：一键启用/停用全部替换（等价于 <code>disable</code> 文件）。</li><li><strong>模块状态</strong>：两张进程卡显示 SystemUI / MiLink 服务是否已加载 hook。</li><li><strong>图片目录</strong>：显示 <code>override</code> 实际路径，一键刷新列表。</li><li><strong>设备卡片列表</strong>：每张卡显示设备名、当前是否命中自定义图。</li><li><strong>使用说明</strong>：4 步上手 + 常见问题排查。</li><li><strong>状态栏与主题</strong>：跟随系统深浅色自动切换，状态栏图标（时间/电量/信号）自动反色。</li><li><strong>项目地址</strong>：页面底部可点击，跳转 GitHub 仓库。</li><li><strong>页脚版本号</strong>：<code>v2.8.8</code>。</li></ul><p>页面只<strong>读取</strong>目录、不会修改你放进去的图片。</p><hr><h2 id="三、开关" tabindex="-1">三、开关 <a class="header-anchor" href="#三、开关" aria-label="Permalink to &quot;三、开关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>方式</th></tr></thead><tbody><tr><td>关闭整个模块</td><td>页面「总开关」关掉，或创建空文件 <code>/sdcard/Download/MiLink_icons/disable</code></td></tr><tr><td>重新开启</td><td>撤销上述操作</td></tr></tbody></table><p>两个进程被 hook 时会先检查该文件，存在则直接跳过，不改任何图。改完需重启 SystemUI 与融合设备中心。</p><hr><h2 id="四、自定义图标" tabindex="-1">四、自定义图标 <a class="header-anchor" href="#四、自定义图标" aria-label="Permalink to &quot;四、自定义图标&quot;">​</a></h2><h3 id="放置路径" tabindex="-1">放置路径 <a class="header-anchor" href="#放置路径" aria-label="Permalink to &quot;放置路径&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sdcard/Download/MiLink_icons/override/</span></span></code></pre></div><blockquote><p>模块页面的「图片目录」卡片里也会直接显示这个路径，可长按复制。</p></blockquote><h3 id="命名方式" tabindex="-1">命名方式 <a class="header-anchor" href="#命名方式" aria-label="Permalink to &quot;命名方式&quot;">​</a></h3><p><strong>设备名（推荐，v2.8 起）</strong></p><p>文件名（不含扩展名）与设备卡片上显示的名字一致即可，例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sdcard/Download/MiLink_icons/override/REDMI Watch 5.webp</span></span>
<span class="line"><span>/sdcard/Download/MiLink_icons/override/小米手机.png</span></span></code></pre></div><p>匹配时<strong>忽略大小写、空格和符号</strong>，所以 <code>REDMIWatch5.webp</code>、<code>redmi_watch_5.webp</code> 都能命中 <code>REDMI Watch 5</code>。</p><h3 id="优先级" tabindex="-1">优先级 <a class="header-anchor" href="#优先级" aria-label="Permalink to &quot;优先级&quot;">​</a></h3><ol><li><code>override/&lt;设备名&gt;.webp|png|jpg|jpeg</code></li><li>APK 内置 <code>assets/icon/&lt;key&gt;.webp</code></li><li>系统原图</li></ol><h3 id="生效方式" tabindex="-1">生效方式 <a class="header-anchor" href="#生效方式" aria-label="Permalink to &quot;生效方式&quot;">​</a></h3><p>改完图后<strong>重启 SystemUI 与融合设备中心</strong>（或重启手机）。模块内部有图片缓存，同一进程内不会重新读盘。</p><h3 id="建议尺寸" tabindex="-1">建议尺寸 <a class="header-anchor" href="#建议尺寸" aria-label="Permalink to &quot;建议尺寸&quot;">​</a></h3><ul><li>建议 ≥ 512×512、透明背景的 PNG/WebP。</li></ul><hr><h2 id="五、内置图标" tabindex="-1">五、内置图标 <a class="header-anchor" href="#五、内置图标" aria-label="Permalink to &quot;五、内置图标&quot;">​</a></h2><p><strong>v2.8.8 起，APK 内只保留一张内置图：<code>assets/icon/watch.webp</code>（手表）。</strong></p><p>其余内置图（phone / notebook / ipad / television / band / watch_square）已在 v2.8.8 移除。也就是说：</p><ul><li>你没在 <code>override/</code> 里放图的设备，会回退到<strong>系统原图</strong>（或空）；</li><li>想让某台设备显示自定义图，请自己在 <code>override/</code> 里放同名文件。</li></ul><p>APK 体积因此从约 993 KB 降到约 341 KB。</p><hr><h2 id="十、更新日志" tabindex="-1">十、更新日志 <a class="header-anchor" href="#十、更新日志" aria-label="Permalink to &quot;十、更新日志&quot;">​</a></h2><h3 id="v2-8-8-versioncode-29" tabindex="-1">v2.8.8（versionCode 29） <a class="header-anchor" href="#v2-8-8-versioncode-29" aria-label="Permalink to &quot;v2.8.8（versionCode 29）&quot;">​</a></h3><ul><li>内置图标精简：<code>assets/icon/</code> 只保留 <code>watch.webp</code>，移除 phone / notebook / ipad / television / band / watch_square 共 6 张。APK 约 993 KB → 341 KB。</li><li>「使用说明 1. 放图片」补上实际目录路径 <code>/sdcard/Download/MiLink_icons/override</code>（独立一行显示）。</li><li>「使用说明 2. 文件名就是设备名」举例改为 <code>REDMI Watch 5.webp</code> / <code>REDMIWatch5.webp</code>。</li></ul><h3 id="v2-8-7-versioncode-28" tabindex="-1">v2.8.7（versionCode 28） <a class="header-anchor" href="#v2-8-7-versioncode-28" aria-label="Permalink to &quot;v2.8.7（versionCode 28）&quot;">​</a></h3><ul><li>新增应用图标（<code>@mipmap/ic_launcher</code>，含 roundIcon，五密度适配）。</li><li>页面底部新增项目地址链接，可点击跳转 GitHub；启动失败时降级为复制到剪贴板并 Toast 提示。</li></ul><h3 id="v2-8-6-versioncode-27" tabindex="-1">v2.8.6（versionCode 27） <a class="header-anchor" href="#v2-8-6-versioncode-27" aria-label="Permalink to &quot;v2.8.6（versionCode 27）&quot;">​</a></h3><ul><li>修复状态栏图标不反色：状态栏透明后系统默认按深色背景处理、使用白色图标，浅色主题下白图标压在浅色背景上不可见。</li><li>新增 <code>applySystemBarIcons(boolean dark)</code>，双 API 兼容不同 OEM。</li></ul><h3 id="v2-8-5-versioncode-26-及更早" tabindex="-1">v2.8.5（versionCode 26）及更早 <a class="header-anchor" href="#v2-8-5-versioncode-26-及更早" aria-label="Permalink to &quot;v2.8.5（versionCode 26）及更早&quot;">​</a></h3><ul><li>设备名匹配（忽略大小写/空格/符号）、<code>RES_ALIAS</code> 别名表、<code>RES_EXCLUDE</code> 非设备图标否决、 尺寸闸门从 intrinsic 改为布局尺寸（v2.6）、模块页面重构等。</li></ul><hr><h2 id="许可" tabindex="-1">许可 <a class="header-anchor" href="#许可" aria-label="Permalink to &quot;许可&quot;">​</a></h2><p>仅供学习交流，修改系统界面资源有风险，请自行评估。</p>`,52)])])}const u=o(r,[["render",d]]);export{b as __pageData,u as default};
